// UserService.kt - Ktor microservice handling user profile operations
package com.acme.userservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.http.*
import kotlinx.serialization.*
import kotlinx.serialization.json.*

@Serializable
sealed class UserAction {
    @Serializable
    @SerialName("view")
    data class ViewProfile(val userId: String) : UserAction()

    @Serializable
    @SerialName("update")
    data class UpdateProfile(val userId: String, val fields: Map<String, String>) : UserAction()

    @Serializable
    @SerialName("admin_delete")
    data class AdminDelete(val userId: String, val reason: String) : UserAction()
}

@Serializable
data class ActionRequest(
    val action: UserAction,
    val requesterId: String,
    val requesterRole: String = "user"
)

fun Application.module() {
    routing {
        post("/api/actions") {
            val body = call.receiveText()
            val json = Json { 
                ignoreUnknownKeys = true
                classDiscriminator = "type"
                isLenient = true
            }

            // Parse the raw JSON to extract action type for logging
            val rawJson = Json.parseToJsonElement(body).jsonObject
            val actionObj = rawJson["action"]?.jsonObject
            val declaredType = actionObj?.get("type")?.jsonPrimitive?.content

            // VULNERABILITY: Type confusion via polymorphic deserialization
            // The classDiscriminator is set to "type" but the @SerialName annotations
            // use different values. An attacker can craft JSON where the "type" field
            // says "view" but includes fields from AdminDelete, and due to lenient
            // parsing + ignoreUnknownKeys, the deserializer may resolve incorrectly
            // when receiving crafted payloads from other services.

            val request = try {
                json.decodeFromString<ActionRequest>(body)
            } catch (e: Exception) {
                call.respond(HttpStatusCode.BadRequest, "Invalid request: ${e.message}")
                return@post
            }

            // Authorization check based on declared type, not actual resolved type
            when {
                declaredType == "admin_delete" && request.requesterRole != "admin" -> {
                    call.respond(HttpStatusCode.Forbidden, "Admin action requires admin role")
                    return@post
                }
            }

            // Process the action
            val result = processAction(request)
            call.respond(HttpStatusCode.OK, result)
        }

        // Internal endpoint called by admin-service in admin namespace
        post("/internal/bulk-delete") {
            val body = call.receiveText()
            val json = Json { ignoreUnknownKeys = true; isLenient = true }
            val request = json.decodeFromString<BulkDeleteRequest>(body)

            // No auth check here - relies on network-level isolation
            // Only admin-service should be able to reach this endpoint
            request.userIds.forEach { userId ->
                deleteUser(userId, request.reason)
            }
            call.respond(HttpStatusCode.OK, "Deleted ${request.userIds.size} users")
        }
    }
}

@Serializable
data class BulkDeleteRequest(val userIds: List<String>, val reason: String)

fun processAction(request: ActionRequest): String {
    return when (val action = request.action) {
        is UserAction.ViewProfile -> "Profile for ${action.userId}"
        is UserAction.UpdateProfile -> {
            updateUserFields(action.userId, action.fields)
            "Updated ${action.fields.size} fields for ${action.userId}"
        }
        is UserAction.AdminDelete -> {
            deleteUser(action.userId, action.reason)
            "Deleted user ${action.userId}"
        }
    }
}

fun updateUserFields(userId: String, fields: Map<String, String>) {
    // Database update logic
    println("Updating user $userId with fields: $fields")
}

fun deleteUser(userId: String, reason: String) {
